package com.geoguy89.cribbage.gfx

/** Maps real latitude and longitude onto an [Outline]'s unit square (the same projection its shoreline used). */
class Projection(private val minX: Float, private val minY: Float, private val scale: Float, private val k: Float) {
    fun x(lon: Double): Float = ((lon * k - minX) / scale).toFloat()
    fun y(lat: Double): Float = ((-lat - minY) / scale).toFloat()
}

/**
 * A real shoreline, simplified from OpenStreetMap (© OpenStreetMap contributors, ODbL). Points are x,y pairs in a box
 * [width] x [height] with the longer side 1, north up.
 */
class Outline(
    val projection: Projection,
    val width: Float,
    val height: Float,
    val outer: FloatArray,
    val islands: List<FloatArray>,
)

